function bootstrapOwnership(f,{name='readiness-77777777-7777-4777-8777-777777777777',started_at=now+60,finished_at=now+80}={}){
 const child=finishProviderEditorAttempt(f,f.editorClaim,{name,phase:'preview-readiness',started_at,finished_at,accepted:false}),diagnostic='Tab 2115966516 is already part of browser session 01a16482-85ce-7741-8416-1c5cf6e9c8a7';
 f.patch(name+'/browser-events.json',s=>{
  Object.assign(s,{failure_code:'STUDIO_PREVIEW_TAB_OWNED',parent_failure_code:'STUDIO_PREVIEW_TAB_OWNED',structured_failure:{code:'STUDIO_PREVIEW_TAB_OWNED',diagnostic:'first exact same-draft candidate getTab was refused because the tab is already bound to another browser session; current URL/pathname recheck unknown'},tool_call_count:6,browser_tool_call_count:6,diagnostics:[diagnostic]});
  Object.assign(s.validation,{failed:true,parent_accepted:false,draft_match:false,voice_match:false,persisted_draft_verified:false,provider_editor_persistence_accepted:false,same_draft_reload_verified:false});
  const events=[{event:'thread.started',tool:null},{event:'turn.started',tool:null},{event:'item.completed',item_id:'SYNTHETIC-warning',item_type:'error',tool:null,diagnostic:'Skill descriptions were shortened to fit the skills context budget.'}];
  for(const [index,api]of ['getState',null,'getBrowser','nameSession','getTab',null].entries()){const item={item_id:'SYNTHETIC-bootstrap-'+index,item_type:'mcp_tool_call',tool:'cua_repl.js',...(api?{api_calls:[api]}:{})};events.push({...item,event:'item.started',status:'in_progress'},{...item,event:'item.completed',status:api==='getTab'?'failed':'completed',response_sha256:'8'.repeat(64),...(api==='getTab'?{failure_class:'ui-result-unknown',diagnostic}:{})});}events.push({event:'turn.completed',tool:null});s.events=events;
 });return child;
}

