test('retained failed browser diagnostics stay unknown while fresh audio facts permit same-owner continuation',t=>{const f=fixture(t),old=finishProviderEditorAttempt(f,f.editorClaim,{name:'readiness-77777777-5555-4555-8555-555555555555',phase:'preview-readiness',started_at:now+60,finished_at:now+80,accepted:false});f.patch(old.name+'/browser-events.json',s=>{s.diagnostics=['preRead is not defined'];s.structured_failure={code:'STUDIO_PREVIEW_BROWSER_UI_ERROR',diagnostic:'Read-only DOM validation did not produce a usable result before reload; verification stopped without retry.'};});assert.equal(createProviderEditorUnknownPersistence(f.createInput()),null);const input={...f.createInput(),current_audio:{present:false,ready_state:0,duration_seconds:null,media_url_sha256:null,generation_in_progress:false}},certificate=createProviderEditorUnknownPersistence(input);assert.ok(certificate);f.write(PROVIDER_EDITOR_UNKNOWN_PERSISTENCE_FILE,certificate);assert.equal(ensureProviderOwnerPreviewAuthorization(f.input),true);assert.ok(inspectOwnerPreviewContinuation(f.input));});


for(const [label,change] of [['security block',s=>{s.diagnostics=['security blocked'];}],['foreign mutation tool',s=>{s.events.find(e=>e.tool).tool='other';s.events.find(e=>e.tool).mcp_server='foreign';s.events.find(e=>e.tool).mcp_tool='generate';}]])test('fresh absent audio cannot erase historical '+label,t=>{const f=fixture(t),h=finishProviderEditorAttempt(f,f.editorClaim,{name:'readiness-77777777-5555-4555-8555-555555555555',phase:'preview-readiness',started_at:now+60,finished_at:now+80,accepted:false});f.patch(h.name+'/browser-events.json',s=>{s.diagnostics=['preRead is not defined'];change(s);});assert.equal(createProviderEditorUnknownPersistence({...f.createInput(),current_audio:{...explicitAbsentAudio}}),null);});

function unfinishedInventory(f){
 const name='readiness-12345678-1234-4234-8234-123456789abc';
 f.write(name+'/browser-attempt.json',{schema:'heygen-studio-browser-attempt-v1',phase:'preview-readiness',request_id,speech_text_sha256,draft_id,started_at:new Date(now+60).toISOString()});
 f.write(name+'/process/process-started.json',{scope:'owned-child-tree',transport:'studio-app-server-stdio',pid:99999999,periodic_run_id:'SYNTHETIC-stale-inventory',started_at:new Date(now+61).toISOString(),deadline_ms:now+80});
 const events=[{event:'thread.started',tool:null},{event:'turn.started',tool:null},{event:'item.started',item_id:'SYNTHETIC-inventory',item_type:'mcp_tool_call',tool:'cua_repl.js',mcp_server:'cua_repl',mcp_tool:'js',api_calls:['getState'],status:'in_progress',response_sha256:null}];
 const file=path.join(f.dir,name,'browser-events.ndjson');fs.writeFileSync(file,events.map(e=>JSON.stringify(e)+'\n').join(''));
 f.input.isProcessAlive=()=>false;return{name,file,events};
}
const explicitAbsent={present:false,ready_state:0,duration_seconds:null,media_url_sha256:null,generation_in_progress:false};
test('dead expired initial inventory history stays unknown and pinned while fresh full proof permits original consent',t=>{
 const f=fixture(t),h=unfinishedInventory(f),before=snapshot(f.dir),c=createProviderEditorUnknownPersistence({...f.createInput(),current_audio:explicitAbsent});assert.ok(c);assert.equal(c.history_reinterpreted,false);assert.ok(c.source_files[h.name+'/browser-events.ndjson']);assert.equal(c.source_files[h.name+'/process/process-exit.json'],undefined);assert.deepEqual(snapshot(f.dir),before);f.write(PROVIDER_EDITOR_UNKNOWN_PERSISTENCE_FILE,c);assert.ok(inspectProviderEditorUnknownPersistence(f.input));fs.appendFileSync(h.file,'{}\n');assert.equal(inspectProviderEditorUnknownPersistence(f.input),null);
});
for(const [label,change]of [
 ['live PID',(f,h)=>f.input.isProcessAlive=()=>true],
 ['unexpired deadline',(f,h)=>f.patch(h.name+'/process/process-started.json',s=>s.deadline_ms=now+1001)],
 ['newer than full read',(f,h)=>f.patch(h.name+'/process/process-started.json',s=>s.deadline_ms=now+101)],
 ['different request',(f,h)=>f.patch(h.name+'/browser-attempt.json',a=>a.request_id='acl_'+'0'.repeat(64))],
 ['different UUID',(f,h)=>f.patch(h.name+'/browser-attempt.json',a=>a.draft_id='0'.repeat(32))],
 ['different speech',(f,h)=>f.patch(h.name+'/browser-attempt.json',a=>a.speech_text_sha256='0'.repeat(64))],
 ['write-capable phase',(f,h)=>f.patch(h.name+'/browser-attempt.json',a=>a.phase='preview')],
 ['foreign tool',(f,h)=>h.events[2].tool='other'],
 ['page creation',(f,h)=>h.events[2].api_calls=['createBrowserTab']],
 ['missing API identity',(f,h)=>delete h.events[2].api_calls],
 ['second call',(f,h)=>h.events.push({...h.events[2],item_id:'SYNTHETIC-other'})],
 ['safety refusal',(f,h)=>h.events.unshift({event:'item.completed',tool:null,item_type:'error',diagnostic:'security blocked'})],
 ['fake exit receipt',(f,h)=>f.write(h.name+'/process/process-exit.json',{})],
 ['fake summary',(f,h)=>fs.writeFileSync(path.join(f.dir,h.name,'browser-events.json'),'{}')],
 ])test('unfinished inventory history rejects '+label,t=>{const f=fixture(t),h=unfinishedInventory(f);change(f,h);fs.writeFileSync(h.file,h.events.map(e=>JSON.stringify(e)+'\n').join(''));assert.equal(createProviderEditorUnknownPersistence({...f.createInput(),current_audio:explicitAbsent}),null);});
test('unfinished inventory history cannot authorize preview from unknown current audio',t=>{const f=fixture(t);unfinishedInventory(f);assert.equal(createProviderEditorUnknownPersistence(f.createInput()),null);});
